use jobrunner::{run_job, RetryConfig, RetryError, FakeSleeper};

#[test]
fn public_api_retries_transient_failures_and_stops_on_success() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("temporary".to_owned())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
